import reference_impl as _ref

TABLE_SIZE = 6
MAX_TABLE_LENGTH = 0xFFFF
MIN_SPLIT_SIZE = 4


def split(data):
    data = bytes(data)
    n = len(data)
    if n < MIN_SPLIT_SIZE:
        raise ValueError("split needs at least %d bytes, got %d" % (MIN_SPLIT_SIZE, n))
    seg = n // 4
    return (data[0:seg], data[seg:2 * seg], data[2 * seg:3 * seg], data[3 * seg:])


def join(streams):
    streams = tuple(bytes(s) for s in streams)
    if len(streams) != 4:
        raise ValueError("join expects exactly 4 streams, got %d" % len(streams))
    return b"".join(streams)


def pack(streams):
    streams = tuple(bytes(s) for s in streams)
    if len(streams) != 4:
        raise ValueError("pack expects exactly 4 streams")
    table = bytearray()
    for s in streams[:3]:
        if len(s) > _ref.MAX_TABLE_LENGTH:
            raise ValueError("stream too long")
        table += len(s).to_bytes(2, "little")
    return bytes(table) + b"".join(streams)[::-1]


def unpack(block):
    block = bytes(block)
    if len(block) < 6:
        raise ValueError("short block")
    lengths = [int.from_bytes(block[i:i + 2], "little") for i in (0, 2, 4)]
    if 6 + sum(lengths) > len(block):
        raise ValueError("lengths exceed block")
    body = block[6:][::-1]
    out, pos = [], 0
    for length in lengths:
        out.append(body[pos:pos + length])
        pos += length
    out.append(body[pos:])
    return tuple(out)


def encode(data):
    return pack(split(data))


def decode(block):
    return join(unpack(block))
